const crypto = require('crypto');
const http = require('http');
const https = require('https');

const baseUrl = $env.AUTOMATION_API_BASE_URL;
const serviceToken = $env.AUTOMATION_SERVICE_TOKEN;
const hmacSecret = $env.AUTOMATION_HMAC_SECRET;
const workerId = $env.AUTOMATION_WORKER_ID;
const workflowName = 'Phase 3 Onboarding Activation Consumer';
const executionId = String($execution.id);

if (!baseUrl || !serviceToken || !hmacSecret || !workerId) {
  throw new Error('AUTOMATION_CONFIGURATION_INVALID');
}

function classificationFor(code) {
  if (['NETWORK_TIMEOUT', 'RATE_LIMITED', 'TEMPORARY_PROVIDER_FAILURE', 'UPSTREAM_5XX'].includes(code)) return 'RETRYABLE';
  if (['INVALID_BUSINESS_STATE', 'MISSING_BUSINESS_CONFIGURATION', 'OPERATIONAL_HOLD'].includes(code)) return 'OPERATOR_REMEDIABLE';
  return 'PERMANENT';
}

async function signedRequest(method, path, body) {
  const bodyText = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const bodyHash = crypto.createHash('sha256').update(bodyText).digest('hex');
  const canonical = `${method}\n${path}\n${timestamp}\n${bodyHash}`;
  const signature = `sha256=${crypto.createHmac('sha256', hmacSecret).update(canonical).digest('hex')}`;
  const target = `${baseUrl}${path}`;
  const transport = baseUrl.startsWith('https://') ? https : http;
  return await new Promise((resolve, reject) => {
    const request = transport.request(target, {
      method,
      headers: {
        authorization: `Bearer ${serviceToken}`,
        'x-automation-timestamp': timestamp,
        'x-automation-signature': signature,
        ...(body === undefined ? {} : { 'content-type': 'application/json' }),
      },
    }, (response) => {
      let responseText = '';
      response.setEncoding('utf8');
      response.on('data', (chunk) => {
        if (responseText.length < 65536) responseText += chunk;
      });
      response.on('end', () => {
        let responseBody = null;
        if (responseText) {
          try { responseBody = JSON.parse(responseText); } catch { responseBody = null; }
        }
        const status = response.statusCode || 0;
        resolve({ response: { status, ok: status >= 200 && status < 300 }, responseBody });
      });
    });
    request.on('error', reject);
    if (body !== undefined) request.write(bodyText);
    request.end();
  });
}

function safeApiCode(responseBody, fallback) {
  const code = responseBody?.error?.code;
  return typeof code === 'string' && /^[A-Z0-9_]+$/.test(code) ? code : fallback;
}

async function reportFailure(claim, code, message, failedNode) {
  const body = {
    eventId: claim.event.eventId,
    runId: claim.run.runId,
    idempotencyKey: claim.run.idempotencyKey,
    workerId,
    n8nExecutionId: executionId,
    failedNode,
    errorCode: code,
    errorMessage: message,
    classification: classificationFor(code),
    reportedAt: new Date().toISOString(),
  };
  const result = await signedRequest('POST', '/api/internal/automation/failure', body);
  if (!result.response.ok) throw new Error('AUTOMATION_FAILURE_REPORT_REJECTED');
}

let claim = null;
let stage = 'claim';
try {
  const claimResult = await signedRequest('POST', '/api/internal/automation/claim', {
    requestId: crypto.randomUUID(),
    workerId,
    workflowName,
  });
  if (claimResult.response.status === 204) {
    return [{ json: { outcome: 'EMPTY' } }];
  }
  if (!claimResult.response.ok || claimResult.responseBody?.kind !== 'CLAIMED') {
    const code = safeApiCode(claimResult.responseBody, 'UNEXPECTED_RESPONSE');
    throw new Error(`AUTOMATION_CLAIM_REJECTED_${claimResult.response.status}_${code}`);
  }
  claim = claimResult.responseBody;

  stage = 'context';
  const query = `runId=${encodeURIComponent(claim.run.runId)}&idempotencyKey=${encodeURIComponent(claim.run.idempotencyKey)}&workerId=${encodeURIComponent(workerId)}`;
  const contextResult = await signedRequest(
    'GET',
    `/api/internal/automation/events/${claim.event.eventId}/context?${query}`,
  );
  if (!contextResult.response.ok) {
    const code = safeApiCode(contextResult.responseBody, 'TEMPORARY_PROVIDER_FAILURE');
    await reportFailure(claim, code, 'The application rejected the current processing context.', 'Load Current Context');
    throw new Error('AUTOMATION_FAILURE_ALREADY_REPORTED');
  }
  const context = contextResult.responseBody;

  stage = 'contract-validation';
  const contractIsValid =
    context?.eventId === claim.event.eventId &&
    context?.runId === claim.run.runId &&
    context?.eventType === 'ONBOARDING_ACTIVATED' &&
    context?.schemaVersion === 1 &&
    context?.onboarding?.status === 'READY_FOR_ONBOARDING' &&
    typeof context?.onboarding?.activatedAt === 'string';
  if (!contractIsValid) {
    await reportFailure(claim, 'INVALID_EVENT_INTEGRITY', 'The context response did not match the supported activation contract.', 'Validate Activation Contract');
    throw new Error('AUTOMATION_FAILURE_ALREADY_REPORTED');
  }

  stage = 'callback';
  const callback = await signedRequest(
    'POST',
    '/api/internal/automation/callback',
    {
      eventId: claim.event.eventId,
      runId: claim.run.runId,
      idempotencyKey: claim.run.idempotencyKey,
      workerId,
      n8nExecutionId: executionId,
      resultStatus: 'COMPLETED',
      externalReferences: {},
    },
  );
  if (!callback.response.ok) {
    throw new Error('AUTOMATION_CALLBACK_REJECTED');
  }
  return [{
    json: {
      outcome: 'COMPLETED',
      eventId: claim.event.eventId,
      runId: claim.run.runId,
      onboardingId: context.onboarding.id,
    },
  }];
} catch (error) {
  if (error instanceof Error && error.message === 'AUTOMATION_FAILURE_ALREADY_REPORTED') throw error;
  if (!claim) {
    if (error instanceof Error && /^AUTOMATION_CLAIM_REJECTED_[0-9]{3}_[A-Z0-9_]+$/.test(error.message)) throw error;
    throw new Error('AUTOMATION_CLAIM_FAILED');
  }
  try {
    await reportFailure(
      claim,
      'TEMPORARY_PROVIDER_FAILURE',
      `The automation consumer failed during ${stage}.`,
      stage,
    );
    throw new Error('AUTOMATION_FAILURE_ALREADY_REPORTED');
  } catch (reportError) {
    if (reportError instanceof Error && reportError.message === 'AUTOMATION_FAILURE_ALREADY_REPORTED') throw reportError;
    const fallback = Buffer.from(JSON.stringify({
      eventId: claim.event.eventId,
      runId: claim.run.runId,
      idempotencyKey: claim.run.idempotencyKey,
      workerId,
      n8nExecutionId: executionId,
      failedNode: stage,
    })).toString('base64url');
    throw new Error(`AUTOMATION_FAILURE_CONTEXT:${fallback}`);
  }
}
